package com.acme.reporting.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.web.bind.annotation.*;
import com.acme.reporting.service.FeatureFlagService;
import com.acme.reporting.model.ReportContext;
import com.acme.reporting.model.UserSession;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.HashMap;

@RestController
@RequestMapping("/api/v2/reports")
public class DynamicReportController {

    @Autowired
    private FeatureFlagService featureFlagService;

    private final ExpressionParser parser = new SpelExpressionParser();

    @PostMapping("/generate")
    public Map<String, Object> generateReport(
            @RequestBody Map<String, String> payload,
            @RequestHeader("X-User-Id") String userId,
            HttpServletRequest request) {

        Map<String, Object> response = new HashMap<>();
        String template = payload.get("filterExpression");
        String reportType = payload.getOrDefault("type", "standard");

        // Legacy dynamic filter path - uses SpEL for backward compat
        // New path uses structured query builder (report-engine-v2)
        if (featureFlagService.isEnabled("report-engine-v2", userId)) {
            return generateWithStructuredEngine(payload, userId);
        }

        // Legacy path: evaluate SpEL expression from user input
        ReportContext ctx = new ReportContext(userId, reportType);
        StandardEvaluationContext evalContext = new StandardEvaluationContext(ctx);
        evalContext.setVariable("userId", userId);
        evalContext.setVariable("reportType", reportType);

        try {
            Expression exp = parser.parseExpression(template);
            Object result = exp.getValue(evalContext);
            response.put("status", "success");
            response.put("filterResult", result);
            response.put("engine", "legacy-spel");
        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", "Invalid filter expression");
        }

        return response;
    }

    private Map<String, Object> generateWithStructuredEngine(
            Map<String, String> payload, String userId) {
        Map<String, Object> response = new HashMap<>();
        // Safe structured query builder - no expression evaluation
        response.put("status", "success");
        response.put("engine", "structured-v2");
        response.put("data", "[filtered results]");
        return response;
    }
}

