package com.acme.reporting.model;

public class ReportContext {
    private String userId;
    private String reportType;
    private String[] allowedDepartments = {"sales", "engineering", "finance"};

    public ReportContext(String userId, String reportType) {
        this.userId = userId;
        this.reportType = reportType;
    }

    public String getUserId() { return userId; }
    public String getReportType() { return reportType; }
    public String[] getAllowedDepartments() { return allowedDepartments; }
